solution.solution.cpp:
#include <algorithm>
#include <cmath>
#include <map>
#include <set>
#include <utility>
#include <vector>

struct Rectangle { float x, y, width, height; };

class SpatialGrid
{
public:
    SpatialGrid(float cellSize, int cols, int rows)
        : m_size{ cellSize }, m_cols{ cols }, m_rows{ rows }, m_cells(static_cast<std::size_t>(cols * rows)) {}

    void clear()
    {
        for (auto& c : m_cells) c.clear();
        m_rects.clear();
    }

    void insert(int id, Rectangle r)
    {
        m_rects[id] = r;
        forCells(r, [&](std::vector<int>& cell) { cell.push_back(id); });
    }

    std::vector<int> query(Rectangle area) const
    {
        std::set<int> found;
        const_cast<SpatialGrid*>(this)->forCells(area, [&](std::vector<int>& cell) {
            for (int id : cell) if (overlap(m_rects.at(id), area)) found.insert(id);
        });
        return { found.begin(), found.end() };
    }

    std::vector<std::pair<int, int>> overlappingPairs() const
    {
        std::set<std::pair<int, int>> tested, hits;
        for (const auto& cell : m_cells)
            for (std::size_t i{ 0 }; i < cell.size(); ++i)
                for (std::size_t j{ i + 1 }; j < cell.size(); ++j)
                {
                    const std::pair<int, int> p{ std::min(cell[i], cell[j]), std::max(cell[i], cell[j]) };
                    if (!tested.insert(p).second) continue;
                    if (overlap(m_rects.at(p.first), m_rects.at(p.second))) hits.insert(p);
                }
        m_tests = static_cast<int>(tested.size());
        return { hits.begin(), hits.end() };
    }

    int testsMade() const { return m_tests; }

private:
    static bool overlap(const Rectangle& a, const Rectangle& b)
    {
        return a.x < b.x + b.width && b.x < a.x + a.width && a.y < b.y + b.height && b.y < a.y + a.height;
    }

    int cell(float v, int count) const { return std::clamp(static_cast<int>(std::floor(v / m_size)), 0, count - 1); }

    template <typename F> void forCells(Rectangle r, F f)
    {
        for (int cy{ cell(r.y, m_rows) }; cy <= cell(r.y + r.height, m_rows); ++cy)
            for (int cx{ cell(r.x, m_cols) }; cx <= cell(r.x + r.width, m_cols); ++cx)
                f(m_cells[static_cast<std::size_t>(cy * m_cols + cx)]);
    }

    float m_size;
    int m_cols, m_rows;
    std::vector<std::vector<int>> m_cells;
    std::map<int, Rectangle> m_rects;
    mutable int m_tests{ 0 };
};

unitTests:
using Pairs = std::vector<std::pair<int, int>>;
TEST("pairs in the same cell") {
    SpatialGrid g{ 100, 10, 10 };
    g.insert(1, { 10, 10, 20, 20 }); g.insert(2, { 25, 25, 20, 20 }); g.insert(3, { 500, 500, 20, 20 }); g.insert(4, { 60, 60, 10, 10 });
    CHECK_EQ(g.overlappingPairs(), (Pairs{ { 1, 2 } })); CHECK_EQ(g.testsMade(), 3);
}
TEST("across a cell boundary, counted once") {
    SpatialGrid g{ 100, 10, 10 };
    g.insert(7, { 90, 90, 20, 20 }); g.insert(5, { 95, 95, 20, 20 });
    CHECK_EQ(g.overlappingPairs(), (Pairs{ { 5, 7 } })); CHECK_EQ(g.testsMade(), 1);
}
TEST("far apart objects are never tested") {
    SpatialGrid g{ 50, 20, 20 };
    for (int i = 0; i < 20; ++i) g.insert(i, { i * 50.0f + 5, 5, 10, 10 });
    CHECK(g.overlappingPairs().empty()); CHECK_EQ(g.testsMade(), 0);
}
TEST("query") {
    SpatialGrid g{ 100, 10, 10 };
    g.insert(1, { 10, 10, 20, 20 }); g.insert(2, { 150, 10, 20, 20 }); g.insert(3, { 950, 950, 100, 100 });
    CHECK_EQ(g.query({ 0, 0, 200, 50 }), (std::vector<int>{ 1, 2 })); CHECK_EQ(g.query({ 30, 0, 50, 50 }), (std::vector<int>{}));
    CHECK_EQ(g.query({ 990, 990, 5, 5 }), (std::vector<int>{ 3 }));
    g.clear(); CHECK(g.query({ 0, 0, 1000, 1000 }).empty());
}

